import { Group, Mesh, PlaneGeometry, DoubleSide, Color, MathUtils } from 'three';
import { MeshStandardNodeMaterial, texture, float } from 'three/tsl';
import { gsap } from 'gsap';
import { WebGPURenderer } from 'three/webgpu';

/**
 * @typedef {Object} NodeConfig
 * @property {Object} textContent
 * @property {Object} visual
 * @property {Array} cinematicPrimitives
 * @property {Object} assets
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>Promise<THREE.Texture>} textureLoader
 * @property {Object.<string, Function>} primitives
 * @property {Object} fontAtlas
 */

/**
 * Create the filmstrip carousel node.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
    // ------------------------------------------------------------------
    // Constants & helpers
    // ------------------------------------------------------------------
    const CARD_WIDTH = 1.6;
    const CARD_HEIGHT = 1.0;
    const CARD_PITCH = 1.85;
    const BEVEL_THICK = 0.025;
    const FOCUS_INDEX = 0; // centre card
    const TOTAL_CARDS = 5;
    const ROT_Y_DEG = -18;
    const ROT_Y_RAD = MathUtils.degToRad(ROT_Y_DEG);
    const SCALE_FOCUSED = 1.0;
    const SCALE_NONFOCUSED = 0.92;
    const OPACITY_NEAR = 1.0;
    const OPACITY_FAR = 0.55;
    const UNDERLINE_HEIGHT = 0.035;
    const UNDERLINE_EMISSIVE = 1.3;

    // ------------------------------------------------------------------
    // Load texture (single source used for all cards)
    // ------------------------------------------------------------------
    const baseTexture = ctx.textureLoader('/prism-mock/home/nodes/parallax-stack.png');
    baseTexture.wrapS = baseTexture.wrapT = THREE.RepeatWrapping;
    baseTexture.minFilter = THREE.LinearMipmapLinearFilter;
    baseTexture.magFilter = THREE.LinearFilter;

    // ------------------------------------------------------------------
    // Group that will hold the whole filmstrip
    // ------------------------------------------------------------------
    const root = new Group();
    root.position.set(0, 0, 0);
    root.rotation.set(0, ROT_Y_RAD, 0);
    root.scale.set(1, 1, 1);
    root.userData = { handlers: {} };

    // ------------------------------------------------------------------
    // Create cards
    // ------------------------------------------------------------------
    const cards = [];

    for (let i = 0; i < TOTAL_CARDS; i++) {
        const idx = i - Math.floor(TOTAL_CARDS / 2); // -2,-1,0,1,2
        const isFocused = idx === FOCUS_INDEX;

        // Container for one card (bevel + plane + underline + caption)
        const cardGroup = new Group();
        cardGroup.position.set(idx * CARD_PITCH, 0, 0);
        cardGroup.scale.set(isFocused ? SCALE_FOCUSED : SCALE_NONFOCUSED, isFocused ? SCALE_FOCUSED : SCALE_NONFOCUSED, 1);
        cardGroup.userData.isFocused = isFocused;

        // ---- Bevel (dark ink plane slightly larger) ----
        const bevelGeom = new PlaneGeometry(CARD_WIDTH + BEVEL_THICK * 2, CARD_HEIGHT + BEVEL_THICK * 2);
        const bevelMat = new MeshStandardNodeMaterial({
            color: new Color('#16161d'),
            side: DoubleSide,
            roughness: 0.6,
            metalness: 0.0,
            clearcoat: 0.0
        });
        const bevelMesh = new Mesh(bevelGeom, bevelMat);
        bevelMesh.position.set(0, 0, -0.001); // slightly behind
        cardGroup.add(bevelMesh);

        // ---- Card plane with texture ----
        const planeGeom = new PlaneGeometry(CARD_WIDTH, CARD_HEIGHT);
        const texNode = texture(baseTexture);
        const cardMat = new MeshStandardNodeMaterial({
            color: new Color('#ffffff'),
            map: texNode,
            roughness: float(0.55),
            metalness: float(0.2),
            clearcoat: float(0.15),
            side: DoubleSide,
            transparent: true,
            opacity: isFocused ? OPACITY_NEAR : OPACITY_FAR
        });
        const cardMesh = new Mesh(planeGeom, cardMat);
        cardMesh.position.set(0, 0, 0);
        cardGroup.add(cardMesh);

        // ---- Underline for focused card ----
        if (isFocused) {
            const underlineGeom = new PlaneGeometry(CARD_WIDTH, UNDERLINE_HEIGHT);
            const underlineMat = new MeshStandardNodeMaterial({
                color: new Color('#ff2a38'),
                emissive: new Color('#ff2a38'),
                emissiveIntensity: UNDERLINE_EMISSIVE,
                side: DoubleSide,
                transparent: true,
                opacity: 1.0
            });
            const underlineMesh = new Mesh(underlineGeom, underlineMat);
            underlineMesh.position.set(0, -CARD_HEIGHT / 2 - UNDERLINE_HEIGHT / 2, 0.001);
            cardGroup.add(underlineMesh);
        }

        // ---- Caption text (below each card) ----
        const captionTexts = [
            'NA-01 MERIDIAN',
            'NA-02 NOCTURNE',
            'NA-03 SIGNAL',
            'NA-04 VANTAGE',
            'NA-05 ARCHIVE'
        ];
        const caption = captionTexts[i];
        // Assuming ctx.fontAtlas.createText returns a THREE.Mesh
        const captionMesh = ctx.fontAtlas.createText({
            text: caption,
            fontFamily: 'JetBrains Mono',
            fontSize: 18,
            fontWeight: 700,
            color: '#e8ecf2',
            align: 'center'
        });
        captionMesh.scale.set(0.13, 0.13, 0.13); // size based on design token (scene‑unit)
        captionMesh.position.set(0, -CARD_HEIGHT / 2 - 0.15, 0.002);
        cardGroup.add(captionMesh);

        root.add(cardGroup);
        cards.push(cardGroup);
    }

    // ------------------------------------------------------------------
    // Headline and body text pinned to scene
    // ------------------------------------------------------------------
    const headlineMesh = ctx.fontAtlas.createText({
        text: 'The collection',
        fontFamily: 'Lora',
        fontSize: 68,
        fontWeight: 600,
        color: '#e8ecf2',
        align: 'left'
    });
    headlineMesh.position.set(-2.6, 1.5, 0);
    headlineMesh.scale.set(0.62, 0.62, 0.62);
    root.add(headlineMesh);

    const bodyMesh = ctx.fontAtlas.createText({
        text: 'Five calibres. One discipline.',
        fontFamily: 'JetBrains Mono',
        fontSize: 26,
        fontWeight: 400,
        color: '#e8ecf2',
        align: 'left'
    });
    bodyMesh.position.set(-2.6, -1.5, 0);
    bodyMesh.scale.set(0.13, 0.13, 0.13);
    root.add(bodyMesh);

    // ------------------------------------------------------------------
    // Apply cinematic primitives (parallax‑scroll)
    // ------------------------------------------------------------------
    if (Array.isArray(config.cinematicPrimitives)) {
        config.cinematicPrimitives.forEach((prim) => {
            const fn = ctx.primitives[prim.name];
            if (typeof fn === 'function') {
                fn(root, prim.params);
            }
        });
    }

    // ------------------------------------------------------------------
    // GSAP timeline for weighted‑settle (snap to nearest card)
    // ------------------------------------------------------------------
    const settleTimeline = gsap.timeline({ paused: true });
    settleTimeline.to(root.position, {
        x: () => {
            const currentX = root.position.x;
            const nearestIdx = Math.round(-currentX / CARD_PITCH);
            const targetX = -nearestIdx * CARD_PITCH;
            return targetX;
        },
        duration: 0.9,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)',
        onUpdate: () => {
            // Overshoot handling
            const overshoot = 1.04;
            const progress = settleTimeline.progress();
            if (progress < 0.5) {
                root.scale.setScalar(overshoot);
            } else {
                root.scale.setScalar(1);
            }
        }
    });

    // Expose a method to trigger settle (could be called by the parallax‑scroll primitive)
    root.userData.settle = () => settleTimeline.restart();

    // ------------------------------------------------------------------
    // Cleanup
    // ------------------------------------------------------------------
    root.userData.cleanup = () => {
        // Dispose textures
        baseTexture.dispose();

        // Dispose materials & geometries
        root.traverse((obj) => {
            if (obj.isMesh) {
                if (obj.geometry) obj.geometry.dispose();
                if (obj.material) {
                    if (Array.isArray(obj.material)) {
                        obj.material.forEach((m) => m.dispose());
                    } else {
                        obj.material.dispose();
                    }
                }
            }
        });

        // Kill GSAP tweens
        gsap.killTweensOf(root);
        gsap.killTweensOf(settleTimeline);
    };

    return root;
}
